'use strict';
// Registers only the current tool's in-memory content, never scans browser storage.
window.ToolBackup={register(opts){
 const make=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n},metaKey='yj-backup-meta-'+opts.id;
 let meta={},timer;try{meta=JSON.parse(localStorage.getItem(metaKey)||'{}')||{}}catch{}
 const fingerprint=()=>{const s=JSON.stringify(opts.get());let a=2166136261,b=5381;for(let i=0;i<s.length;i++){a=Math.imul(a^s.charCodeAt(i),16777619);b=Math.imul(b,33)^s.charCodeAt(i)}return s.length+':'+(a>>>0)+':'+(b>>>0)},panel=make('section'),row=make('div'),out=make('button','导出完整备份'),label=make('label',opts.preview?'导入差异与合并':'恢复备份'),file=make('input'),info=make('p'),note=make('p','仅备份此工具的数据。文件在本机处理，不上传；备份未加密，请妥善保管。清理网站数据、换设备前请先下载。');
 panel.className='yj-backup-panel';panel.dataset.tool=opts.id;panel.setAttribute('aria-label','本工具完整备份');row.className='yj-backup-row';out.type='button';label.className='yj-backup-file';file.type='file';file.accept='.json,application/json';file.setAttribute('aria-label','恢复完整备份');label.append(file);info.className='yj-backup-info';info.setAttribute('role','status');note.className='yj-backup-note';row.append(out,label);panel.append(row,info,note);
 const host=opts.host?document.querySelector(opts.host):document.querySelector('main');if(!host)return;const footer=host.querySelector(':scope > footer');if(footer)host.insertBefore(panel,footer);else host.append(panel);
 function paint(){try{const changed=fingerprint()!==meta.fingerprint,old=!Number.isFinite(meta.at)||Date.now()-meta.at>=7*86400000;info.textContent=(Number.isFinite(meta.at)?'上次发起备份下载：'+new Date(meta.at).toLocaleString('zh-CN')+'。':'尚未下载完整备份。')+(changed&&old?' 有未备份内容，建议现在下载。':changed?' 内容已有变化，请定期下载。':' 当前内容与上次备份一致。');panel.classList.toggle('yj-backup-due',changed&&old)}catch{info.textContent='暂时无法读取备份状态，请检查本工具内容。'}}
 function marked(){try{meta={at:Date.now(),fingerprint:fingerprint()};localStorage.setItem(metaKey,JSON.stringify(meta))}catch{}paint()}
 function download(){try{const content=JSON.stringify(opts.get(),null,2);if(content.length>20*1024*1024)throw Error('备份超过 20 MB，请减少内容后重试');const blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),a=make('a');a.href=url;a.download=opts.name+'-完整备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);marked()}catch(e){info.textContent='导出失败：'+e.message}}
 out.onclick=download;
 file.onchange=async()=>{try{const f=file.files[0];if(!f)return;if(f.size>20*1024*1024)throw Error('备份不能超过 20 MB');const raw=await f.text(),v=JSON.parse(raw);if(opts.preview){await opts.preview(v);info.textContent='已打开差异预览，尚未写入。请在预览中确认合并。';return}if(opts.restore){const next=opts.validate(v);if(!window.confirm('恢复备份会替换此工具当前内容。建议先导出完整备份。是否继续？'))return;if(await opts.restore(next)===false)throw Error('本工具未应用恢复，请检查页面提示');info.textContent='备份已恢复。';paint()}else{const expected=opts.get();if(!v||expected.app&&v.app!==expected.app||expected.format&&v.format!==expected.format)throw Error('请选择此工具的完整备份，不能用其他工具或结果文件恢复');const target=document.querySelector(opts.import);if(!target)throw Error('恢复入口不可用');const dt=new DataTransfer();dt.items.add(new File([raw],f.name,{type:'application/json'}));target.files=dt.files;target.dispatchEvent(new Event('change',{bubbles:true}));info.textContent='文件已交给本工具检查，请按提示确认恢复。'}}catch(e){info.textContent='未恢复：'+e.message}finally{file.value=''}};
 // Older tools lacked confirmation before destructive actions; preserve newer tools' own dialogs.
 if(opts.id==='quiz')document.addEventListener('click',e=>{if(e.target.closest('#clear,#builtin')&&!window.confirm('这会移除当前工具的学习记录。请先导出完整备份，是否继续？')){e.preventDefault();e.stopImmediatePropagation()}},true);
 if(['quiz','prompter','display'].includes(opts.id))document.addEventListener('change',e=>{if(e.target.id==='remember'&&!e.target.checked&&!window.confirm('关闭保存会移除此工具的本机记录，当前内容暂留内存。请先下载完整备份，是否继续？')){e.target.checked=true;e.stopImmediatePropagation()}},true);
 if(opts.id==='display')document.querySelector(opts.import)?.addEventListener('change',e=>{if(e.target.files.length&&!window.confirm('导入会替换当前展示页面和背景。建议先导出完整备份，是否继续？')){e.target.value='';e.stopImmediatePropagation()}},true);
 const changed=()=>{clearTimeout(timer);timer=setTimeout(paint,500)};document.addEventListener('input',changed);document.addEventListener('change',changed);document.addEventListener('click',changed);window.addEventListener('storage',e=>{if(e.key===metaKey){try{meta=JSON.parse(e.newValue||'{}')||{}}catch{}paint()}});
 // Existing result/CSV/image exports are deliberately not counted as full backups.
 if(opts.export){document.querySelector(opts.export)?.addEventListener('click',()=>{if(!opts.canMark||opts.canMark())marked()})}
 paint();return{download,refresh:paint};
}};

